WITH "r0" AS ( SELECT "s".* FROM "public"."comment" AS "s" WHERE true AND "s"."body" = $1 ORDER BY "s"."id" ASC NULLS LAST LIMIT 3 ) SELECT coalesce(json_agg( row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" , "t0"."body" AS "text" , "c2"."j" AS "article" ) AS "%")) ORDER BY "t0"."id" ASC NULLS LAST ), '[]') FROM "r0" AS "t0" LEFT JOIN LATERAL (SELECT row_to_json((SELECT "%" FROM (SELECT "t1"."title" AS "headline" , "c1"."j" AS "author" ) AS "%")) AS "j" FROM ( SELECT "s".* FROM "public"."article" AS "s" WHERE true AND "s"."id" = "t0"."article_id" LIMIT 1 ) AS "t1" LEFT JOIN LATERAL (SELECT row_to_json((SELECT "%" FROM (SELECT "t2"."name" AS "name" ) AS "%")) AS "j" FROM ( SELECT "s".* FROM "public"."author" AS "s" WHERE true AND "s"."id" = "t1"."author_id" LIMIT 1 ) AS "t2" ) AS "c1" ON true ) AS "c2" ON true
